insert into public.menu_items(id,name,category,diet,price_paise,description,short_description,image_urls,published,is_available,sort_order) values
('be2a8ba9-e8fb-992b-ca88-e6d1e89f13f7','Fish Pollichathu','main','non-veg',54500,'Whole fish rubbed with Kerala masala and cooked in a banana-leaf parcel. The leaf traps the steam, keeping the fish tender and carrying the aroma of the spices to the table.','Whole fish, Kerala masala and the aroma of roasted banana leaf.',array[]::text[],true,true,0),
('c5fd6a67-0b2d-6b57-f766-823252964578','Prawns Kizhi','main','non-veg',59500,'Prawns tossed in coastal spices and served in a roasted banana-leaf parcel. Open the leaf to catch the aroma of the masala, then spoon the prawns over fragrant ghee rice.','Coastal spices tucked into a roasted banana-leaf parcel.',array[]::text[],true,true,10),
('4513236a-eb06-a252-c96d-d8fca9549918','Kerala Chicken Dum Biriyani','main','non-veg',34500,'Fragrant dum-cooked rice layered with spiced chicken and fried onions. Slow cooking lets the rice take on the aroma of the chicken and spices, with caramelised onions adding a sweet finish.','',array[]::text[],true,true,20),
('e5b9cbe1-eb76-01bf-94f2-8b8563b8285d','Paneer Tikka','starter','veg',29500,'Spice-marinated paneer with peppers and onions, grilled until the edges char. The paneer stays soft in the centre, while the vegetables bring sweetness and a little crunch.','',array[]::text[],true,false,30),
('200518af-11fe-e100-3331-14d9f3fff9a7','Kerala Payasam','dessert','veg',15500,'A slow-cooked Kerala dessert with jaggery and coconut milk. The jaggery gives it a deep caramel sweetness, and the coconut milk rounds it out into a mellow finish.','A slow-cooked finish with jaggery and coconut milk.',array[]::text[],true,true,40),
('08bdd7eb-f277-ddf7-7656-076be91742d2','Garden Fresh Green Salad','salad','veg',19500,'Crisp greens, cool cucumber and juicy tomatoes tossed in a light dressing. It makes a refreshing first course or a fresh contrast to a rich curry.','',array[]::text[],true,true,50),
('29a76212-b6b8-8eaa-869f-58a90add3fbf','Chicken Kizhi','main','non-veg',36500,'Spiced chicken served in an opened banana-leaf parcel. The leaf holds in the aroma as it cooks, and a piece of paratha makes a good scoop for the masala.','',array[]::text[],true,true,60),
('c00d8445-91c5-00a0-3b1e-5eb164aa3b0f','Seafood Soup','soup','non-veg',23500,'A light coastal broth with pieces of seafood. The broth keeps the seafood flavour in front, making this a lighter start before a curry or biriyani.','',array[]::text[],true,true,70),
('6aee5d6a-3f26-e3bd-5e0e-db9e7f44ab88','Cream of Broccoli Soup','soup','veg',18500,'Broccoli blended into a smooth, creamy soup with a mild vegetal sweetness. A good choice if you want a gentle, comforting start to the meal.','',array[]::text[],true,true,80),
('170ace72-5aa5-66d7-7f2e-7159c6d357a0','Lemon Coriander Soup','soup','veg',16500,'A light broth brightened with lemon and fresh coriander. The citrus gives it a clean finish, with the herbs lifting the aroma as you take the first spoonful.','',array[]::text[],true,true,90),
('45d2d96a-e01c-b28d-3be6-e28df336e833','Vegetable Manchow Soup','soup','veg',17500,'A savoury Indo-Chinese soup with finely chopped vegetables and bold seasoning. The classic crispy noodle topping gives the broth a satisfying crunch.','',array[]::text[],true,true,100),
('0a408fb8-af86-63b0-7ade-221c6d0bfdba','Vegetable Pasta Salad','salad','veg',22500,'Pasta tossed with chopped vegetables for a mix of tender bites and fresh crunch. A lighter option alongside a grilled starter or a bowl of soup.','',array[]::text[],true,true,110),
('ad5cea9d-6718-fcca-3942-fefc3342e903','Fruit Chaat Salad','salad','veg',19500,'Bite-sized seasonal fruit tossed chaat style. A little tang and spice balance the sweetness, and the fruit selection may vary with the season.','',array[]::text[],true,true,120),
('7ee2257c-ea91-b19d-4436-a0ce6706c51e','Chicken 65','starter','non-veg',31500,'A South Indian starter of bite-sized, spice-coated chicken with crisp edges. Serve it as a first bite to share before the mains arrive.','',array[]::text[],true,true,130),
('1b5d369e-3bff-a34e-90ac-4abdb584c98c','Kerala Fish Fry','starter','non-veg',37500,'Fish coated in Kerala-style masala and fried until the outside develops a deep, crisp crust. A squeeze of lime brings out the flavour of the fish and spices.','',array[]::text[],true,false,140),
('38a18bff-0678-4cdc-93aa-c0cfe0266b5a','Crispy Fried Vegetables','starter','veg',24500,'Assorted vegetables fried in a light coating until golden. The crisp outside gives way to tender vegetables, making it an easy starter to share.','',array[]::text[],true,true,150),
('973e2c9a-96a6-79f8-a0cc-b51e4c06cc32','Prawns Tawa Fry','starter','non-veg',49500,'Prawns seared on a hot tawa so the masala clings to the edges. Expect a little char on the outside and a firm, juicy bite inside.','',array[]::text[],true,true,160),
('7c1ce5b1-8014-9e5f-5e29-5eb94805b740','Kerala Fish Curry','main','non-veg',39500,'Fish simmered in a bold Kerala-style curry with a tangy edge. Spoon the gravy over rice to catch the full flavour of the coastal spices.','',array[]::text[],true,true,170),
('9ed096ee-eb2a-6dd8-485b-7475788ba3d9','Kovalam Prawns Curry','main','non-veg',52500,'Prawns served in a richly spiced coastal gravy. The sweet bite of the prawns stands out against the masala, especially with a simple side of rice.','',array[]::text[],true,true,180),
('9c72d352-2a2c-15e8-a8b7-bb9ea0a395aa','Paneer Butter Masala','main','veg',32500,'Soft paneer cubes in a smooth, buttery masala. The mellow gravy makes it a natural match for naan, which can soak up the sauce.','',array[]::text[],true,true,190),
('4b704c23-60fd-820a-a19d-72092c9c45a0','Vegetable Kurma','main','veg',24500,'Mixed vegetables cooked in a gently spiced, creamy gravy. The soft vegetables and mild sauce work well with either flaky paratha or a side of rice.','',array[]::text[],true,true,200),
('3313b647-157a-ff6a-a834-3b3fd53ce60f','Vegetable Dum Biriyani','main','veg',26500,'Fragrant rice and spiced vegetables cooked together dum style. The rice takes on the aroma of the spices, with vegetables adding colour and texture throughout.','',array[]::text[],true,true,210),
('c2bd5450-e826-e0f6-f1b5-aa85821f2faf','Gulab Jamun','dessert','veg',14500,'Soft, golden dumplings soaked in sweet syrup. The syrup seeps into the centre, so each bite stays tender and sweet from the first bite to the last.','',array[]::text[],true,true,220),
('0a4f5a38-0099-e854-8321-69c20f9c23a6','Rice Kheer','dessert','veg',15500,'Rice cooked slowly in milk until the grains are soft and the pudding turns creamy. Its gentle sweetness makes for a quieter finish after a spiced main.','',array[]::text[],true,false,230),
('34c5ac59-2348-9f2e-7b5a-b85f0989a8bb','Ice Cream','dessert','veg',12500,'A cold, creamy finish after a warm meal. Ask your server which flavours are available today, especially if you would like to pair a scoop with another dessert.','',array[]::text[],true,true,240),
('384431c0-d7d7-bef0-7ab9-422d99982533','Lime Mint','drink','veg',11500,'A chilled lime refresher with fresh mint. The lime gives it a tart first sip, followed by a cool herbal finish that suits grilled dishes and spicy starters.','',array[]::text[],true,true,250),
('935a4961-7861-7abf-39ab-1322469c6995','Lime Soda','drink','veg',10500,'Fresh lime with fizzy soda for a bright, crisp drink. The bubbles and citrus make it a refreshing companion to fried starters and richer mains.','',array[]::text[],true,true,260),
('d617b988-5cdc-e049-bc03-0a0dbe23bad4','Masala Tea','drink','veg',7500,'Indian milk tea brewed with warming spices. The tea brings a little bitterness, the milk softens it, and the spice aroma lingers after each sip.','',array[]::text[],true,true,270),
('7bf815d7-e6a1-ff88-bf9f-32dd004cc045','Kerala Lassi','drink','veg',12500,'A chilled yoghurt drink with a smooth, thick texture and a gentle tang. It makes a cooling companion to a meal with plenty of spice.','',array[]::text[],true,true,280),
('91963b3d-4939-4442-2b2f-90a399c944ea','Kerala Paratha','side','veg',4500,'A layered Kerala flatbread with flaky edges and a soft centre. Pull apart a layer and use it to scoop up fish masala, kurma, or a thick curry.','',array[]::text[],true,true,290),
('3650e351-fff8-f833-6988-70af7de250d4','Butter Naan','side','veg',6500,'Soft naan brushed with butter, with lightly blistered patches on the surface. Its tender centre is especially good for scooping up a creamy paneer gravy.','',array[]::text[],true,true,300),
('d9cfa165-a0bb-edad-0916-e4fc18475255','Ghee Rice','side','veg',17500,'Fluffy rice scented with ghee for a gently nutty aroma. Its mild flavour makes room for the masala in a prawn parcel or a spoonful of fish curry.','',array[]::text[],true,true,310);
